import io.btrace.core.annotations.*;
import static io.btrace.core.BTraceUtils.*;

@BTrace
public class CheckoutProbe {
  @TLS static long t0;
  static long fraudN, fraudErr, fraudNs, fraudMax, payN, payNs, payMax;

  @OnMethod(clazz="com.acme.risk.FraudScreen", method="screen", location=@Location(Kind.RETURN))
  public static void fraudOk(@Duration long d) { fraudN++; fraudNs += d; if (d > fraudMax) fraudMax = d; }

  @OnMethod(clazz="com.acme.risk.FraudScreen", method="screen", location=@Location(Kind.ERROR))
  public static void fraudEx(Throwable t, @Duration long d) { fraudN++; fraudErr++; fraudNs += d; if (d > fraudMax) fraudMax = d; }

  @OnMethod(clazz="com.acme.payments.PaymentClient", method="authorize", location=@Location(Kind.RETURN))
  public static void payOk(@Duration long d) { payN++; payNs += d; if (d > payMax) payMax = d; }

  @OnTimer(5000)
  public static void report() {
    println(strcat("fraud n=", str(fraudN)));
    println(strcat(" err=", str(fraudErr)));
    println(strcat(" avgMs=", str(fraudN == 0 ? 0 : fraudNs / fraudN / 1000000)));
    println(strcat(" maxMs=", str(fraudMax / 1000000)));
    println(strcat("pay n=", str(payN)));
    println(strcat(" avgMs=", str(payN == 0 ? 0 : payNs / payN / 1000000)));
    println(strcat(" maxMs=", str(payMax / 1000000)));
  }
}

